    CHECK(c.engine == "vsim:ax45mpv_premium");
    CHECK(c.trigger == "marker");
    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
    CHECK(c.passthrough.empty());
  }

  // Selection axes, --flag=value form.
  {
    Cli c = parse_cli({"run", "--mode=cycle", "--engine=vsim:x"});
    CHECK(c.error.empty());
    CHECK(c.model == "cycle");
    CHECK(c.engine == "vsim:x");
  }

  // The `--` boundary: everything after it is verbatim passthrough, even
  // tokens that look like framework flags (they must NOT be parsed).
  {
    Cli c = parse_cli({"run", "--mode", "fast", "prog.elf", "--", "-gdb",
                       "tcp::1234", "-S", "--mode", "IGNORED"});
    CHECK(c.error.empty());
    CHECK(c.model == "fast");
    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
    CHECK(c.passthrough.size() == 5);
    CHECK(c.passthrough[0] == "-gdb");
    CHECK(c.passthrough[1] == "tcp::1234");
    CHECK(c.passthrough[4] == "IGNORED");
  }

  // A `--` with nothing after it parses cleanly (empty passthrough).
  {
    Cli c = parse_cli({"run", "--mode", "fast", "--"});
    CHECK(c.error.empty());
    CHECK(c.passthrough.empty());
  }

  // Per-subcommand help.
  {
...
    CHECK(c.subcommand == "list");
    CHECK(c.positional.size() == 1 && c.positional[0] == "fixtures");
  }

  // Hybrid pc-trigger boundaries (symbol + 0x address), space-separated form.
  {
    Cli c = parse_cli({"run", "--mode", "hybrid", "--trigger", "pc",
                       "--pc-start", "main", "--pc-end", "0x80001234",
                       "prog.elf"});
    CHECK(c.error.empty());
    CHECK(c.pc_start == "main");
    CHECK(c.pc_end == "0x80001234");
    CHECK(c.positional.size() == 1 && c.positional[0] == "prog.elf");
  }

  // Hybrid mem size; mixes space and =forms.
  // --mmap-size is the retired spelling, kept as a hidden alias of --mem-size.
  {
    Cli c = parse_cli({"run", "--mode", "hybrid", "--trigger", "marker",
                       "--mmap-size=64M", "prog.elf"});
    CHECK(c.error.empty());
    CHECK(c.mem_size == "64M");
  }

  // The icount/warmup knobs were removed: --qemu-icount / --vsim-icount /
  // --vsim-warmup-icount are now unknown options.
  {
    Cli c = parse_cli({"run", "--mode", "hybrid", "--qemu-icount", "10",
                       "prog.elf"});
    CHECK(!c.error.empty());
    Cli d = parse_cli({"run", "--mode", "hybrid", "--vsim-icount", "10",
                       "prog.elf"});
    CHECK(!d.error.empty());
    Cli e = parse_cli({"run", "--mode", "hybrid", "--vsim-warmup-icount", "500",
                       "prog.elf"});
    CHECK(!e.error.empty());
  }

  // --what was a placeholder for a never-wired `build` subcommand: it parsed
  // but no command read it, so it silently swallowed its value everywhere.
  // Removed -- now an unknown option like any other.
=== test_check.hpp ===
// Tiny assert-and-count harness shared by the driver's standalone unit tests
// (cli_test, json_test, and F5+ infra tests). No doctest dependency: each test
// is its own executable, calls CHECK(...) for each assertion, and ends with
// `return andes_sim::test::report("<name>");`.
#ifndef ANDESIM_TEST_CHECK_HPP
#define ANDESIM_TEST_CHECK_HPP

#include <cstdio>
#include <string>
#include <vector>

namespace andes_sim::test {

inline int g_failures = 0;

inline int report(const char* what) {
  if (g_failures) {
    std::fprintf(stderr, "%d check(s) failed\n", g_failures);
    return 1;
  }
  std::printf("all %s checks passed\n", what);
  return 0;
}

}  // namespace andes_sim::test

#define CHECK(cond)                                                        \
  do {                                                                     \
    if (!(cond)) {                                                         \
      std::fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
      ++andes_sim::test::g_failures;                                       \
    }                                                                      \
  } while (0)

namespace andes_sim::test {

// Element-wise compare two string vectors: CHECK the size, then each element,
// printing got/want on the first mismatch. `label` tags the diff line. Shared
// by the driver's argv-shaped unit tests (plan_test, run_test). Defined after
// CHECK so the macro is in scope.
inline void check_eq(const std::vector<std::string>& got,
                     const std::vector<std::string>& want, const char* label) {
  CHECK(got.size() == want.size());
  const size_t n = got.size() < want.size() ? got.size() : want.size();
  for (size_t i = 0; i < n; ++i) {
    if (got[i] != want[i])
      std::fprintf(stderr, "  %s[%zu]: got '%s' want '%s'\n", label, i,
                   got[i].c_str(), want[i].c_str());
    CHECK(got[i] == want[i]);
  }
}

}  // namespace andes_sim::test

#endif  // ANDESIM_TEST_CHECK_HPP

