#include "options.hpp"

namespace andes_sim {
namespace {

// Rows are grouped by command and, inside a group, in the order help should
// print them: filtering the one table by a command's bit yields that command's
// list, already ordered. The globals come last, so they close every help.
const std::vector<Option>& table() {
  static const std::vector<Option> kOptions = {
      // ---- run -------------------------------------------------------------
      {.flag = "--mode",
       .arity = Arity::Value,
       .cmds = kRunCmd,
       .str = &Cli::model,
       .metavar = "fast|cycle|hybrid",
       .tag = "REQUIRED",
       .brief = "which mode to run"},
      {.flag = "--trigger",
       .arity = Arity::Value,
       .cmds = kRunCmd,
       .str = &Cli::trigger,
       .metavar = "marker|pc",
       .tag = "REQUIRED for hybrid",
       .brief = "the ROI delimiter"},
      {.flag = "--pc-start",
       .arity = Arity::Value,
       .cmds = kRunCmd,
       .str = &Cli::pc_start,
       .indent = 1,
       .metavar = "<sym|0x>",
       .tag = "REQUIRED for --trigger pc",
       .brief = "ROI start boundary"},
      {.flag = "--pc-end",
       .arity = Arity::Value,
       .cmds = kRunCmd,
       .str = &Cli::pc_end,
       .indent = 1,
       .metavar = "<sym|0x>",
       .tag = "REQUIRED for --trigger pc",
       .brief = "ROI end boundary"},
      {.flag = "--engine",
       .arity = Arity::Value,
       .cmds = kRunCmd,
       .str = &Cli::engine,
       .metavar = "<id>",
       .brief = "pick an engine, e.g. vsim:ax45mpv_premium (default: the sole one)"},
      {.flag = "--mem-size",
       .arity = Arity::Value,
       .cmds = kRunCmd,
       .str = &Cli::mem_size,
       .metavar = "<spec>",
       .brief = "guest RAM, e.g. 256M / 2G (hybrid: max 2G; fast: QEMU -m; cycle: ignored)"},
      {.flag = "--runtime",
       .arity = Arity::Value,
       .cmds = kRunCmd,
       .str = &Cli::runtime,
       .metavar = "linux",
       .brief = "run a Linux-ABI program (static glibc) under the vlinux proxy "
                "kernel; the default is a bare-metal ELF. See "
                "runtime/linux/README.md"},
      {.flag = "--dry-run",
       .cmds = kRunCmd,
       .on = &Cli::dry_run,
       .brief = "print the exact engine command(s) and exit, running nothing (fast/cycle/hybrid)"},
      {.flag = "--print-memmap",
       .cmds = kRunCmd,
       .on = &Cli::print_memmap,
       .brief = "print the hybrid guest memory map and exit, running nothing (hybrid only; ELF optional)"},
      {.flag = "--verify",
       .cmds = kRunCmd,
       .on = &Cli::verify,
       .brief = "cross-check the hybrid run against a QEMU oracle"},
      {.flag = "--kanata",
       .arity = Arity::Value,
       .cmds = kRunCmd,
       .str = &Cli::kanata,
       .metavar = "<file>",
       .brief = "write a Kanata pipeline trace of the ROI (hybrid only; open in Konata)"},
      {.flag = "--objdump",
       .arity = Arity::Value,
       .cmds = kRunCmd,
       .str = &Cli::objdump,
       .indent = 1,
       .metavar = "<file>",
       .brief = "embed that objdump -d dump's disassembly in the trace (requires --kanata)"},
      {.flag = "--gdb",
       .cmds = kRunCmd,
       .on = &Cli::gdb,
       .brief = "pause at startup for a debugger (fast: QEMU stub; cycle: vsim JTAG + $ICEMAN; not hybrid)"},
      {.flag = "--gdb-port",
       .arity = Arity::Value,
       .cmds = kRunCmd,
       .str = &Cli::gdb_port,
       .metavar = "<port>",
       .brief = "override the --gdb port (fast 1234, cycle 9104)"},
      {.flag = "--step-timeout-ms",
       .arity = Arity::Value,
       .cmds = kRunCmd,
       .str = &Cli::step_timeout_ms,
       .metavar = "<ms>",
       .brief = "hybrid per-leg spawn timeout (default 90000); raise it for a large ROI on the cycle-accurate leg"},
      {.arity = Arity::Boundary,
       .cmds = kRunCmd,
       .brief = "forward everything after -- verbatim to the engine (fast/cycle); "
                "hybrid rejects -- args, EXCEPT --runtime linux, where they are app argv",
       .label = "  -- <args...>"},

      // ---- profile ---------------------------------------------------------
      {.flag = "--engine",
       .arity = Arity::Value,
       .cmds = kProfileCmd,
       .str = &Cli::engine,
       .metavar = "<id>",
       .brief = "the engine whose QEMU config to profile on (default: the sole one)"},
      {.flag = "--limit",
       .arity = Arity::Value,
       .cmds = kProfileCmd,
       .str = &Cli::limit,
       .metavar = "<N>",
       .brief = "report the top-N loops (default 50)"},
      {.flag = "--min-iters",
       .arity = Arity::Value,
       .cmds = kProfileCmd,
       .str = &Cli::min_iters,
       .metavar = "<N>",
       .brief = "drop loops with fewer iterations (default 1)"},
      {.flag = "--no-optimize-rvv",
       .cmds = kProfileCmd,
       .on = &Cli::optimize_rvv,
       .sets = false,
       .brief = "keep scalar loops too (default: RVV-only)"},
      {.flag = "--optimize-rvv",
       .cmds = kProfileCmd,
       .on = &Cli::optimize_rvv,
       .brief = "RVV loops only -- the default; undoes an earlier --no-optimize-rvv"},
      {.flag = "--no-llm",
       .cmds = kProfileCmd,
       .on = &Cli::llm,
       .sets = false,
       .brief = "plain table instead of the LLM Markdown report"},
      {.flag = "--llm",
       .cmds = kProfileCmd,
       .on = &Cli::llm,
       .brief = "the LLM Markdown report -- the default; undoes an earlier --no-llm"},
      {.flag = "--no-source",
       .cmds = kProfileCmd,
       .on = &Cli::no_source,
       .brief = "skip source file:line resolution (addr2line)"},
      {.flag = "--objdump",
       .arity = Arity::Value,
       .cmds = kProfileCmd,
       .str = &Cli::objdump,
       .metavar = "<bin>",
       .brief = "override the disassembler (default: $HYBRID_TOOLCHAIN's)"},
      {.flag = "--addr2line",
       .arity = Arity::Value,
